return {["sort"]=0,["roomList"]={{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_02]],["connectPoint"]=0,["name"]=[[卧室]],["permission"]=1,["enterable"]=1,["dsc"]=[[有些破旧的卧室，摆设着一张床榻，上面的被褥缝缝补补有很多补丁，一旁的矮木桌上有个破烂的竹筐，装着一件尚未缝补好的破布衣。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[卧室(fb44_01)]],["canLeave"]=1,["id"]=[[fb44_01]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[堂屋]],["permission"]=1,["left"]=[[fb44_01]],["fullName"]=[[堂屋(fb44_02)]],["enterable"]=1,["dsc"]=[[堂屋前贴着两张被撕掉一半的对联，正中奉的画像既不是菩萨，也不是自家先祖，倒像是药王。堂屋门口还有两个竹架子，共三层，用竹筛晒着许多草药。]],["down"]=[[fb44_04]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc30]],["canLeave"]=1,["id"]=[[fb44_02]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_04]],["connectPoint"]=0,["name"]=[[猪圈]],["permission"]=1,["enterable"]=1,["dsc"]=[[很小的猪圈，顶多能养下一头幼崽。满地的干草和粪便，让人看了就不想踏足。一旁的墙壁上挂有犁耙农具，整整齐齐，与猪圈中的杂乱颇不符合。]],["fullName"]=[[猪圈(fb44_03)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc29]],["canLeave"]=1,["id"]=[[fb44_03]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[小院子]],["permission"]=1,["left"]=[[fb44_03]],["fullName"]=[[小院子(fb44_04)]],["enterable"]=1,["up"]=[[fb44_02]],["dsc"]=[[一个破旧的小院子，院子周围的篱笆已经倒了不少，地上还有鸡鸭的羽毛。左侧的角落里还放着一个巨大的磨盘，但是家中并无拉磨的牲口，所以看上去从未使用过。]],["down"]=[[fb44_05]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc28]],["canLeave"]=1,["id"]=[[fb44_04]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_06]],["connectPoint"]=0,["name"]=[[民房]],["permission"]=1,["enterable"]=0,["up"]=[[fb44_04]],["dsc"]=[[民房的门墙低矮，墙上白漆剥落，角落里长满了杂草，似乎很久都没有人清理。且细细观察，发现周围撒有雄黄粉。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[民房(fb44_05)]],["canLeave"]=1,["id"]=[[fb44_05]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[水井]],["permission"]=1,["left"]=[[fb44_05]],["fullName"]=[[水井(fb44_06)]],["enterable"]=1,["dsc"]=[[空旷的平地上只有一口水井，水井旁放有两个水桶，里面还装有半桶水。]],["down"]=[[fb44_12]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc31]],["canLeave"]=1,["id"]=[[fb44_06]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[酒馆]],["permission"]=1,["fullName"]=[[酒馆(fb44_07)]],["enterable"]=1,["dsc"]=[[一个很小的酒馆，就放着三张木桌，角落的墙壁边有几坛子酒尚未开封，但红封上隐有灰尘。看来多是因村内贫瘠，人们即便到了酒馆，也未能有几文闲钱买酒。]],["down"]=[[fb44_13]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc15]],["unit2"]=[[npc24c]],["unit1"]=[[npc24]],["canLeave"]=1,["id"]=[[fb44_07]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_09]],["connectPoint"]=0,["name"]=[[东门]],["permission"]=1,["enterable"]=1,["dsc"]=[[雅张村东门，用多根粗木所支成的高大门框，上头歪歪倒倒的用木牌写着“雅张村”三字。两旁有两棵歪脖子老树，树枝光秃，上头还有根粗麻绳，不知用来做什么。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[东门(fb44_08)]],["canLeave"]=1,["id"]=[[fb44_08]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[叉路口]],["permission"]=1,["left"]=[[fb44_08]],["fullName"]=[[叉路口(fb44_09)]],["enterable"]=1,["dsc"]=[[两条道路相叉交汇之地，不远处有一条小河，河岸边有几只被遗弃的破鞋、破烂衣服。]],["down"]=[[fb44_17]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc32b]],["canLeave"]=1,["id"]=[[fb44_09]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[草丛里]],["permission"]=1,["enterable"]=1,["dsc"]=[[和人一般高的草丛，地上全是泥沼，听闻村里的老人说这里原本是一个小池塘，因为大旱干涸后才变为荒芜之地，从此再也没有一滴水从地下涌出，杂草横生。]],["down"]=[[fb44_19]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[草丛里(fb44_10)]],["canLeave"]=1,["id"]=[[fb44_10]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_12]],["connectPoint"]=0,["name"]=[[稻田]],["permission"]=1,["enterable"]=1,["dsc"]=[[四四方方的稻田，田间种植水稻，但因此地水源不足，水稻略有些枯黄，且田间时有龟裂之地，偶尔能听到田蛙的叫声。]],["down"]=[[fb44_21]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[稻田(fb44_11)]],["canLeave"]=1,["id"]=[[fb44_11]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_13]],["connectPoint"]=0,["name"]=[[晒谷场]],["permission"]=1,["left"]=[[fb44_11]],["fullName"]=[[晒谷场(fb44_12)]],["enterable"]=1,["up"]=[[fb44_06]],["dsc"]=[[晒谷场上堆放着几个麻袋，还有一辆小推车。几把农具随意的靠在一旁的大树下，大树半倾，底下的根部已经露出，似倒非倒。]],["down"]=[[fb44_22]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc47b]],["canLeave"]=1,["id"]=[[fb44_12]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_14]],["connectPoint"]=0,["name"]=[[大榕树下]],["permission"]=1,["left"]=[[fb44_12]],["enterable"]=1,["up"]=[[fb44_07]],["dsc"]=[[一棵巨大的榕树，树下支着几把破旧的躺椅，周围多杂草、泥土，偶尔有几个小贩蹲在这里售卖蔬果，但均无人问津。四周除了鸟叫虫鸣，常常安静的吓人。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[大榕树下(fb44_13)]],["canLeave"]=1,["id"]=[[fb44_13]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_15]],["connectPoint"]=0,["name"]=[[芙蓉客栈]],["permission"]=1,["left"]=[[fb44_13]],["fullName"]=[[芙蓉客栈(fb44_14)]],["enterable"]=1,["dsc"]=[[雅张村内唯一的客栈，有上下两层，下层摆放桌椅，上层则是一间间供人休息的小屋。客栈开在雅张村已经多年了，但生意惨淡，故而有些破旧却无钱修整。]],["down"]=[[fb44_23]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc39]],["unit1"]=[[npc47k]],["canLeave"]=1,["id"]=[[fb44_14]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[客栈后院]],["permission"]=1,["left"]=[[fb44_14]],["enterable"]=1,["dsc"]=[[芙蓉客栈的后院，院内堆放着许多杂物，看起来很久都没有打理过。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[客栈后院(fb44_15)]],["canLeave"]=1,["id"]=[[fb44_15]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_17]],["connectPoint"]=0,["name"]=[[小路]],["permission"]=1,["enterable"]=1,["dsc"]=[[乡间小路，两侧都是田地，路旁生有杂草、野花，偶尔因为下雨会使得道路十分泥泞。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[小路(fb44_16)]],["canLeave"]=1,["id"]=[[fb44_16]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_18]],["connectPoint"]=0,["name"]=[[杂树林]],["permission"]=1,["left"]=[[fb44_16]],["fullName"]=[[杂树林(fb44_17)]],["enterable"]=1,["up"]=[[fb44_09]],["dsc"]=[[附近稀稀松松的长有很多不知名的杂树，且树干纤细，树叶大多凋零，使得地面堆积了不少落叶。少有野兽出没，顶多能看到一两只野兔。]],["down"]=[[fb44_24]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc42f]],["unit2"]=[[npc07]],["unit1"]=[[npc06]],["canLeave"]=1,["id"]=[[fb44_17]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_19]],["connectPoint"]=0,["name"]=[[杂树林]],["permission"]=1,["left"]=[[fb44_17]],["enterable"]=1,["dsc"]=[[附近稀稀松松的长有很多不知名的杂树，且树干纤细，树叶大多凋零，使得地面堆积了不少落叶。少有野兽出没，顶多能看到一两只野兔。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[杂树林(fb44_18)]],["canLeave"]=1,["id"]=[[fb44_18]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_20]],["connectPoint"]=0,["name"]=[[青草地]],["permission"]=1,["left"]=[[fb44_18]],["enterable"]=1,["up"]=[[fb44_10]],["dsc"]=[[宽广的青草地，杂草遍野，因为是村民们进出雅张村的必经之路，所以被踩出了一条小道。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[青草地(fb44_19)]],["canLeave"]=1,["id"]=[[fb44_19]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_21]],["connectPoint"]=0,["name"]=[[小池塘]],["permission"]=1,["left"]=[[fb44_19]],["enterable"]=1,["dsc"]=[[池塘算不得深，绕着整个池子走一圈也只需数百步，里面飘着浮萍，有几朵开败的荷花。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[小池塘(fb44_20)]],["canLeave"]=1,["id"]=[[fb44_20]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_22]],["connectPoint"]=0,["name"]=[[田埂]],["permission"]=1,["left"]=[[fb44_20]],["enterable"]=1,["up"]=[[fb44_11]],["dsc"]=[[细长的田埂，两旁被人挖出了两条小流，偶然能够看到几只蝌蚪，周围的杂草时常会被清理的很干净。]],["down"]=[[fb44_26]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[田埂(fb44_21)]],["canLeave"]=1,["id"]=[[fb44_21]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[田埂]],["permission"]=1,["left"]=[[fb44_21]],["enterable"]=1,["up"]=[[fb44_12]],["dsc"]=[[细长的田埂，两旁被人挖出了两条小流，偶然能够看到几只蝌蚪，周围的杂草时常会被清理的很干净。]],["down"]=[[fb44_27]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[田埂(fb44_22)]],["canLeave"]=1,["id"]=[[fb44_22]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[长巷]],["permission"]=1,["enterable"]=1,["up"]=[[fb44_14]],["dsc"]=[[细长的窄巷，只容得下一人来往，若两人迎面还需要其中一人侧身方能同行。且巷中墙壁爬满干枯的藤枝，看上去一派死寂。]],["down"]=[[fb44_28]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[长巷(fb44_23)]],["canLeave"]=1,["id"]=[[fb44_23]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[杂树林]],["permission"]=2,["enterable"]=1,["up"]=[[fb44_17]],["dsc"]=[[附近稀稀松松的长有很多不知名的杂树，且树干纤细，树叶大多凋零，使得地面堆积了不少落叶。少有野兽出没，顶多能看到一两只野兔。]],["down"]=[[fb44_30]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[杂树林(fb44_24)]],["canLeave"]=1,["id"]=[[fb44_24]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[佛堂]],["permission"]=1,["fullName"]=[[佛堂(fb44_25)]],["enterable"]=1,["dsc"]=[[佛堂内供奉有观音大士，两侧为其坐下童子。三个蒲团并列，前方桌案上有香炉三鼎、瓜果数盘。置身其中心态祥和，再观佛像慈眉善目，心之所安。]],["down"]=[[fb44_31]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc47l]],["canLeave"]=1,["id"]=[[fb44_25]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_27]],["connectPoint"]=0,["name"]=[[稻田]],["permission"]=1,["enterable"]=1,["up"]=[[fb44_21]],["dsc"]=[[四四方方的稻田，田间种植水稻，但因此地水源不足，水稻略有些枯黄，且田间时有龟裂之地，偶尔能听到田蛙的叫声。]],["fullName"]=[[稻田(fb44_26)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc47d]],["canLeave"]=1,["id"]=[[fb44_26]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_28]],["connectPoint"]=0,["name"]=[[稻田]],["permission"]=1,["left"]=[[fb44_26]],["enterable"]=1,["up"]=[[fb44_22]],["dsc"]=[[四四方方的稻田，田间种植水稻，但因此地水源不足，水稻略有些枯黄，且田间时有龟裂之地，偶尔能听到田蛙的叫声。]],["down"]=[[fb44_32]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[稻田(fb44_27)]],["canLeave"]=1,["id"]=[[fb44_27]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_29]],["connectPoint"]=0,["name"]=[[小路]],["permission"]=1,["left"]=[[fb44_27]],["enterable"]=1,["up"]=[[fb44_23]],["dsc"]=[[一条笔直的小路，地面石板凹凸不平，还有不少的泥土，走起来很容易弄脏鞋袜。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[小路(fb44_28)]],["canLeave"]=1,["id"]=[[fb44_28]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[药铺]],["permission"]=1,["left"]=[[fb44_28]],["enterable"]=1,["dsc"]=[[雅张村附近唯一的一间药铺，里头药材种类繁多，正应了那句“麻雀虽小五脏俱全”。但也因此，药铺掌柜坐地起价，寻常的雅张村村民根本买不起药铺中的药，所以很少有人会来此。]],["fullName"]=[[药铺(fb44_29)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc04]],["canLeave"]=1,["id"]=[[fb44_29]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[沿湖大道]],["permission"]=2,["fullName"]=[[沿湖大道(fb44_30)]],["enterable"]=1,["up"]=[[fb44_24]],["dsc"]=[[大道两侧植绿柳，湖面波纹不惊。因为数年前的一场干旱，湖水几乎干涸，近年虽有缓和，但湖中的水泥沙混杂，难以饮用。]],["down"]=[[fb44_36]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc47c]],["canLeave"]=1,["id"]=[[fb44_30]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[紫竹庵]],["permission"]=1,["enterable"]=1,["up"]=[[fb44_25]],["dsc"]=[[位居山林紫竹中的庵堂，以此得名。庵堂大门口用金漆所写的匾额已经褪色，想来是近两年香火减少所致。过了庵堂前院就是两进的正堂，前奉释迦牟尼，后奉阿难、迦叶尊者。]],["down"]=[[fb44_37]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[紫竹庵(fb44_31)]],["canLeave"]=1,["id"]=[[fb44_31]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[山坡]],["permission"]=1,["enterable"]=1,["up"]=[[fb44_27]],["dsc"]=[[略微陡峭的山坡，道旁还有不少落石堆积，零落的生有几丛杂草。]],["down"]=[[fb44_41]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[山坡(fb44_32)]],["canLeave"]=1,["id"]=[[fb44_32]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_34]],["connectPoint"]=0,["name"]=[[山道]],["permission"]=1,["enterable"]=1,["dsc"]=[[曲折的山道，树木很少，一侧临崖，因为道路少有人修整，所以若是马车很难在山道上行走。]],["down"]=[[fb44_42]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[山道(fb44_33)]],["canLeave"]=1,["id"]=[[fb44_33]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb44_35]],["connectPoint"]=0,["name"]=[[山脚渔村]],["permission"]=1,["left"]=[[fb44_33]],["enterable"]=1,["dsc"]=[[位于山脚的渔村，村内人家并不多，但每户人家前都晒有渔网、放有鱼竿。浓重的腥味四溢，地上不时可以看到鱼鳞。]],["fullName"]=[[山脚渔村(fb44_34)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc47i]],["canLeave"]=1,["id"]=[[fb44_34]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[浅滩]],["permission"]=1,["left"]=[[fb44_34]],["enterable"]=1,["dsc"]=[[沙石浅滩，放有几艘用来打渔的小舟。从此眺望可见青山连绵，远处还有飞鸟盘桓不下，几尾鲜鱼不时跃出。]],["fullName"]=[[浅滩(fb44_35)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[